#!/usr/bin/env python3
"""Build report, full source-scope orders, sensitivity tables and explicit dispatch contract offline."""
from pathlib import Path
import sys
sys.dont_write_bytecode=True
import json,gzip,csv,re,hashlib,subprocess,tempfile,collections,os
from build_turnout import COUNTIES,FIPS,CANDS,rank
D=Path(__file__).resolve().parent;E=D/'extract';S=D/'source';STATE=D.parent.parent

def read(p):return json.loads(p.read_text())
def zread(p):return json.loads(gzip.decompress(p.read_bytes()))
def dump(p,v):p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def pct(n,d):return f'{100*n/d:.10f}'
def csvwrite(p,rs):
 with p.open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
def receipt(sid):return read(S/(sid+'.receipt.json'))
def url(sid):
 a=receipt(sid);return a.get('requested_url',a.get('url'))
def link(sid,label):return f'[{label}]({url(sid)})'
def main():
 m=read(E/'native-rows.json');b=read(E/'ballot-rows.json');bf=read(E/'ballot-footers.json');controls=read(E/'state-candidate-controls.json');tc=read(E/'turnout-controls.json');summary=read(D/'rank-summary.json');audit=read(D/'native-audit.json')
 orders={};sens=[]
 for scope,rr in m.items():
  orders[scope],s=rank([{**r,'volume':sum(v for v in r['values'] if v is not None)} for r in rr],'volume');sens.append({'scope':scope,'measure':'reported_named_candidate_votes',**s})
 for year,rr in b.items():
  for field in ['ballots_cast','registered_voters']:
   available=[{**r,'volume':r[field]} for r in rr if r[field] is not None]
   sc=year+'-'+field;orders[sc],s=rank(available,'volume');sens.append({'scope':sc,'measure':field,'excluded_null_field_keys':[r['key'] for r in rr if r[field] is None],**s})
 dump(D/'all-source-orders.json',orders);dump(D/'sensitivity.json',sens)
