 section=ct.split('NEW JERSEY',1)[1].split('FOR UNITED STATES REPRESENTATIVE',1)[0]
 (E/'clerk-2020-new-jersey-section.txt').write_text(section)
 vals={}
 for name,pat in [('Cory Booker',r'Cory A\. Booker[^\n]+?([\d,]+)\s*$'),('Rikin Mehta',r'Rikin[^\n]+?Mehta[^\n]+?([\d,]+)\s*$')]:
  mt=re.search(pat,section,re.M);assert mt;vals[name]=int(mt[1].replace(',',''))
 dump(S/'clerk-2020-reference.json',{'reference_path':os.path.relpath(cp,S),'raw_sha256':hashlib.sha256(cb).hexdigest(),'raw_bytes':len(cb),'url':'https://clerk.house.gov/member_info/electionInfo/2020/statistics2020.pdf','acquisition':'existing read-only primary original; this worker did not fetch it; independent section extraction','inherited_receipt_path':'../../../../michigan/data/baselines/primary-source-2020.json','candidate_controls':vals})
 # Stable current source chain inventory, all21, roles remain distinct.
